from pptx import Presentation
from pptx.util import Cm, Pt, Emu

prs = Presentation('/home/user/Desktop/42_2.pptx')

print("=== Slide 3 verification ===")
for shape in prs.slides[2].shapes:
    if shape.shape_type == 13:  # PICTURE
        print(f"  {shape.name}: H={Emu(shape.height).cm:.4f}cm, W={Emu(shape.width).cm:.4f}cm")
    elif shape.shape_type == 6:  # GROUP
        for sub in shape.shapes:
            if sub.shape_type == 13:
                print(f"  {shape.name} > {sub.name}: H={Emu(sub.height).cm:.4f}cm, W={Emu(sub.width).cm:.4f}cm")

print("\n=== Slide 6 verification ===")
for shape in prs.slides[5].shapes:
    if shape.has_text_frame:
        for para in shape.text_frame.paragraphs:
            for run in para.runs:
                print(f"  {shape.name}: '{run.text[:40]}', size={run.font.size}")
EOF
